    if (conn == null)
      return false;
    if (!_decoder.retain_boundary_request(_decoder_session, key))
      return false;
    int correction_offset = correction_offset(conn, snapshot.word.length());
    _preserve_autocorrect_boundary_transition = true;
    boolean inserted;
    try
    {
