private void save()
{
  if (_prefs == null)
    return;
  SharedPreferences.Editor editor = _prefs.edit();
  editor.putInt(PREF_VOCABULARY_POLICY_VERSION,
      VOCABULARY_POLICY_VERSION);
  save_counts(editor, PREF_WORDS, _word_counts);
  if (_word_surfaces.isEmpty())
    editor.remove(PREF_WORD_SURFACES);
  else
    editor.putStringSet(PREF_WORD_SURFACES,
        encode_word_surfaces(_word_surfaces));
  if (_taught_words.isEmpty())
    editor.remove(PREF_TAUGHT_WORDS);
  else
    editor.putStringSet(PREF_TAUGHT_WORDS,
        new HashSet<String>(_taught_words));
  save_counts(editor, PREF_BIGRAMS, _bigram_counts);
  if (_correction_counts.isEmpty())
    editor.remove(PREF_CORRECTIONS);
  else
    editor.putStringSet(PREF_CORRECTIONS,
        encode_corrections(_correction_counts));
  if (_contextual_correction_counts.isEmpty())
    editor.remove(PREF_CONTEXTUAL_CORRECTIONS);
  else
    editor.putStringSet(PREF_CONTEXTUAL_CORRECTIONS,
        encode_contextual_corrections(_contextual_correction_counts));
  if (_replacement_rules.isEmpty())
    editor.remove(PREF_REPLACEMENTS);
  else
    editor.putStringSet(PREF_REPLACEMENTS,
        encode_replacement_rules(_replacement_rules));
  if (_touch_samples == 0)
  {
    editor.remove(PREF_TOUCH_SAMPLES);
    editor.remove(PREF_TOUCH_OFFSET_X);
    editor.remove(PREF_TOUCH_OFFSET_Y);
  }
  else
  {
    editor.putInt(PREF_TOUCH_SAMPLES, _touch_samples);
    editor.putFloat(PREF_TOUCH_OFFSET_X, _touch_offset_x);
    editor.putFloat(PREF_TOUCH_OFFSET_Y, _touch_offset_y);
  }
  editor.apply();
}

private static void save_counts(SharedPreferences.Editor editor,
    String preference, Map<String, Integer> counts)
{
  if (counts.isEmpty())
    editor.remove(preference);
  else
    editor.putStringSet(preference, encode_counts(counts));
}

private static Set<String> encode_counts(Map<String, Integer> counts)
{
  Set<String> out = new HashSet<String>();
  for (Map.Entry<String, Integer> entry : counts.entrySet())
    out.add(entry.getKey() + "\t" + entry.getValue());
  return out;
}

  private void run_control(Control control)
  {
    boolean externalControl = control.kind == ControlKind.EXPLICIT_LEARN
      || control.kind == ControlKind.EXPLICIT_REPLACEMENT;
    if (!externalControl)
      install_personalization(control.personalizationSpecEpoch,
          control.personalization);
    boolean feedback = false;
    try
    {
      switch (control.kind)
      {
        case RECORD:
          install_resources(control.source.request.key.resourceEpoch,
              control.source.resources);
          if (control.selectedCorrection && control.correctedFrom != null)
            _workerPersonalization.record_selected_correction(
                control.correctedFrom, control.word);
          else
          {
            boolean recognized = control.recognized != null
              ? control.recognized.booleanValue()
              : is_recognized_worker(control.source, control.word);
            if (recognized)
              _workerPersonalization.record_commit(control.word, null,
                  control.source.request.typed,
                  control.source.request.touches);
            else
              _workerPersonalization.reset_context();
          }
          break;
        case LEARN:
        {
          long generation = _workerPersonalization.generation();
          _workerPersonalization.learn_word(control.word);
          feedback = _workerPersonalization.generation() != generation;
          break;
        }
        case EXPLICIT_LEARN:
          feedback = new PersonalizationStore(
              control.personalization.preferences).learn_word(control.word);
          break;
        case REPLACEMENT:
          _workerPersonalization.set_replacement(
              control.word, control.correctedFrom);
          break;
        case EXPLICIT_REPLACEMENT:
          new PersonalizationStore(control.personalization.preferences)
            .set_replacement(control.word, control.correctedFrom);
          break;
        case UNLEARN:
          feedback = _workerPersonalization.unlearn_word(control.word);
          break;
        case CLEAR:
          _workerPersonalization.clear();
          break;
        case RESET:
          _workerPersonalization.reset_context();
          break;
      }
    }
